import csv
with open('outputs/t10_accessibility_scores.csv', 'r') as f:
    reader = csv.DictReader(f)
    min_score = float('inf')
    max_score = float('-inf')
    for row in reader:
        score = float(row['accessibility_score'])
        if score < min_score:
            min_score = score
        if score > max_score:
            max_score = score
    print(f'Min score: {min_score}')
    print(f'Max score: {max_score}')
    if min_score >= 0 and max_score <= 1:
        print('All scores are between 0 and 1')
    else:
        print('ERROR: Some scores are outside [0, 1]')
